CREATE OR REPLACE FUNCTION "public"."media_avaliacoes"("p_user_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    media DECIMAL;
BEGIN
    SELECT ROUND(AVG(nota)::numeric, 2) INTO media
    FROM avaliacoes
    WHERE destinatario_id = p_user_id;
    RETURN COALESCE(media, 0);
END;
$$;


ALTER FUNCTION "public"."media_avaliacoes"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pode_impulsionar"("p_tatuador_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN NOT EXISTS (
        SELECT 1 FROM boosts
        WHERE tatuador_id = p_tatuador_id
          AND data_inicio > NOW() - INTERVAL '7 days'
    );
END;
$$;


ALTER FUNCTION "public"."pode_impulsionar"("p_tatuador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tatuadores_proximos"("p_latitude" numeric, "p_longitude" numeric, "p_raio_km" numeric DEFAULT 10) RETURNS TABLE("tatuador_id" "uuid", "nome" character varying, "distancia_km" numeric)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        t.tatuador_id,
        u.nome,
        ROUND((ST_Distance(
            e.geo_point,
            ST_SetSRID(ST_MakePoint(p_longitude, p_latitude), 4326)::geography
        ) / 1000)::numeric, 2) AS distancia_km
    FROM tatuadores t
    JOIN users u ON u.user_id = t.user_id
    LEFT JOIN estudios es ON es.estudio_id = t.estudio_id
    JOIN enderecos e ON e.owner_id = COALESCE(es.estudio_id, t.tatuador_id)
    WHERE t.perfil_completo = TRUE
      AND t.termos_aceitos = TRUE
      AND u.status_ativo = TRUE
      AND ST_DWithin(
          e.geo_point,
          ST_SetSRID(ST_MakePoint(p_longitude, p_latitude), 4326)::geography,
          p_raio_km * 1000
      )
    ORDER BY distancia_km ASC;
END;
$$;


ALTER FUNCTION "public"."tatuadores_proximos"("p_latitude" numeric, "p_longitude" numeric, "p_raio_km" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_chat_last_message"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    UPDATE chats SET ultima_mensagem_em = NEW.data_envio WHERE chat_id = NEW.chat_id;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_chat_last_message"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_geo_point"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF NEW.latitude IS NOT NULL AND NEW.longitude IS NOT NULL THEN
        NEW.geo_point := ST_SetSRID(ST_MakePoint(NEW.longitude, NEW.latitude), 4326)::geography;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_geo_point"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_modified_column"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.data_modificacao = NOW();
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_modified_column"() OWNER TO "postgres";

