CREATE TABLE IF NOT EXISTS "public"."enderecos" (
    "endereco_id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "owner_id" "uuid" NOT NULL,
    "owner_type" "public"."endereco_owner_type" NOT NULL,
    "cep" character varying(9) NOT NULL,
    "logradouro" character varying(200) NOT NULL,
    "numero" character varying(20),
    "complemento" character varying(100),
    "bairro" character varying(100),
    "cidade" character varying(100) NOT NULL,
    "uf" character(2) NOT NULL,
    "latitude" numeric(10,8),
    "longitude" numeric(11,8),
    "geo_point" "public"."geography"(Point,4326),
    "data_criacao" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "chk_lat_lng" CHECK (((("latitude" IS NULL) AND ("longitude" IS NULL)) OR ((("latitude" >= ('-90'::integer)::numeric) AND ("latitude" <= (90)::numeric)) AND (("longitude" >= ('-180'::integer)::numeric) AND ("longitude" <= (180)::numeric)))))
);


ALTER TABLE "public"."enderecos" OWNER TO "postgres";


