CREATE POLICY "mensagens_select_participants" ON "public"."mensagens" FOR SELECT USING (("chat_id" IN ( SELECT "c"."chat_id"
   FROM (("public"."chats" "c"
     JOIN "public"."clientes" "cl" ON (("cl"."cliente_id" = "c"."cliente_id")))
     JOIN "public"."tatuadores" "t" ON (("t"."tatuador_id" = "c"."tatuador_id")))
  WHERE ((("cl"."user_id")::"text" = ("auth"."uid"())::"text") OR (("t"."user_id")::"text" = ("auth"."uid"())::"text")))));



